interface Entitas {
  id: number;
}
class Gudang<T extends Entitas> {
  private data = new Map<number, T>();
  simpan(x: T): void {
    this.data.set(x.id, x);
  }
  cari(id: number): T | undefined {
    return this.data.get(id);
  }
  semua(): T[] {
    return [...this.data.values()];
  }
  cariBerdasarkan<K extends keyof T>(kunci: K, nilai: T[K]): T[] {
    return this.semua().filter((x) => x[kunci] === nilai);
  }
}
