const g = new Gudang<Barang>();
g.simpan({ id: 1, nama: "Gula", kategori: "sembako" });
g.simpan({ id: 2, nama: "Sabun", kategori: "mandi" });
g.simpan({ id: 3, nama: "Beras", kategori: "sembako" });
console.log(g.cari(2)?.nama);
console.log(g.cariBerdasarkan("kategori", "sembako").map((b) => b.nama));

