interface Entitas {
  id: number;
}
class Gudang<T extends Entitas> {
  private data = new Map<number, T>();
  simpan(x: T): void {
    this.data.set(x.id, x);
  }
  cari(id: number): T | undefined {
    return this.data.get(id);
  }
  perbarui(id: number, ubah: Partial<Omit<T, "id">>): boolean {
    const lama = this.data.get(id);
    if (!lama) return false;
    this.data.set(id, { ...lama, ...ubah });
    return true;
  }
}
type Barang = Entitas & { nama: string; stok: number };
const g = new Gudang<Barang>();
g.simpan({ id: 1, nama: "Gula", stok: 5 });
const a = g.perbarui(1, { stok: 9 });
console.log(a, g.cari(1)?.stok, g.perbarui(7, { stok: 1 }));
